from _lib import *
lesson("future-perfect-and-continuous", "Czasy zaawansowane", "Future perfect i future continuous", 10,
 "Future continuous (will be doing) opisuje czynność w trakcie w konkretnym momencie przyszłości lub zaplanowany, rutynowy przebieg wydarzeń. Future perfect (will have done) mówi o czynności zakończonej przed danym momentem w przyszłości. Future perfect continuous (will have been doing) podkreśla, jak długo coś będzie trwało do danego momentu.",
 "Te czasy pozwalają precyzyjnie mówić o planach, terminach i prognozach (by 2030, by the time…). Częste w esejach o przyszłości, w Speaking (spekulowanie) i w Part 4.",
 dict(scheme="will be + -ing | will have + past participle | will have been + -ing", word_order="This time tomorrow I'll be flying. / By June I'll have finished. / By May I'll have been working here for 10 years.",
      affirmative=["This time next week I'll be lying on a beach.", "By 2030 we will have reduced emissions by half.", "By Friday she'll have been working on it for a month."],
      negative=["I won't be using the car tomorrow.", "They won't have finished by the deadline."],
      questions=["Will you be passing the post office?", "Will they have arrived by the time we get there?"]),
 [X("At 8 p.m. tomorrow I'll be watching the match.", "Jutro o 20:00 będę oglądał mecz.", "Czynność w trakcie w przyszłości."),
  X("Don't call at noon – I'll be having lunch.", "Nie dzwoń w południe – będę jadł obiad.", "Future continuous."),
  X("Will you be using the printer this afternoon?", "Czy będziesz korzystał z drukarki po południu?", "Grzeczne pytanie o plany."),
  X("The train will be arriving at platform 4.", "Pociąg wjedzie na peron 4.", "Zaplanowany przebieg."),
  X("By the end of the year, I'll have saved enough for a car.", "Do końca roku odłożę dość na samochód.", "Zakończone przed momentem w przyszłości."),
  X("She'll have left by the time you arrive.", "Zanim przyjedziesz, ona już wyjdzie.", "By the time + present simple."),
  X("By 2050, many species will have disappeared.", "Do 2050 roku wiele gatunków zniknie.", "Prognoza w eseju."),
  X("Next month we'll have been married for twenty years.", "W przyszłym miesiącu minie dwadzieścia lat, odkąd jesteśmy małżeństwem.", "Czasownik stanu → future perfect simple."),
  X("By June, he'll have been studying English for five years.", "W czerwcu minie pięć lat, odkąd uczy się angielskiego.", "Czas trwania → perfect continuous."),
  X("I won't have finished the report before Monday.", "Nie skończę raportu przed poniedziałkiem.", "Przeczenie."),
  X("You'll have heard the news, I suppose.", "Pewnie słyszałeś już wiadomość.", "Future perfect jako przypuszczenie o teraźniejszości.")],
 [C("will do vs will be doing", "Will do – decyzja, obietnica, przewidywanie; will be doing – czynność w toku w przyszłości lub zwykły bieg rzeczy.", "Will you be coming? brzmi grzeczniej niż Will you come?"),
  C("will have done vs will have been doing", "Simple – rezultat (ile, co skończone); continuous – długość trwania.", "I'll have read 3 books / I'll have been reading for 3 hours."),
  C("by vs until", "By – najpóźniej do; until – aż do (ciągle do tego momentu).", "I'll have finished by 5 / I'll be working until 5.")],
 [W("By the time you will arrive, I'll have cooked.", "By the time you arrive, I'll have cooked.", "Po by the time/when/before – czas teraźniejszy."),
  W("This time tomorrow I'll lie on the beach.", "This time tomorrow I'll be lying on the beach.", "Moment w trakcie → continuous."),
  W("By 2030 they will finish the bridge.", "By 2030 they will have finished the bridge.", "By + moment → perfect."),
  W("I'll have been knowing her for ten years.", "I'll have known her for ten years.", "Know to czasownik stanu – bez -ing.")],
 ["Czasowniki stanu (know, own, believe, be) nie występują w formach continuous.",
  "Future perfect może wyrażać przypuszczenie o przeszłości: They'll have landed by now.",
  "W zdaniach czasowych używamy present perfect zamiast future perfect: When I've finished, I'll call."],
 [dict(en="By the time the policy takes effect, millions will have lost their savings.", pl="Zanim polityka wejdzie w życie, miliony stracą oszczędności.", note="By the time + present simple + future perfect."),
  dict(en="Within a decade, electric cars will have overtaken petrol cars in sales.", pl="W ciągu dekady samochody elektryczne prześcigną spalinowe pod względem sprzedaży.", note="Within + okres."),
  dict(en="Ministers will be meeting union leaders throughout the week.", pl="Ministrowie będą się spotykać z liderami związków przez cały tydzień.", note="Styl prasowy.")],
 [G("This time next week we ___ (fly) to Lisbon.", ["will be flying", "'ll be flying"], "Czynność w trakcie."),
  G("By the time you get home, I ___ (finish) dinner.", ["will have finished", "'ll have finished"], "Zakończone przed momentem."),
  G("By December, she ___ (work) here for ten years.", ["will have been working", "'ll have been working", "will have worked"], "Czas trwania."),
  M("Don't ring at 9 – we ___ the children to bed.", ["will be putting", "will have put", "put", "are put"], "will be putting", "W trakcie o 9.", {"will have put": "Oznaczałoby, że już skończymy.", "put": "Brak formy przyszłej.", "are put": "Strona bierna – zły sens."}),
  G("They ___ (not / complete) the road by the summer.", ["won't have completed", "will not have completed"], "Przeczenie future perfect."),
  K("I will finish the essay before Friday.", "HAVE", "I ___ the essay by Friday.", ["will have finished", "'ll have finished", "will have written"], "By + future perfect."),
  K("Are you going to use your laptop tonight?", "BE", "Will ___ laptop tonight?", ["you be using your"], "Future continuous w pytaniu."),
  E("When I will see her, I'll tell her.", ["When I see her, I'll tell her.", "When I see her"], "Po when – present simple.")],
 [G("In 2030 I ___ (live) in this flat for twenty years.", ["will have lived", "will have been living", "'ll have lived"], "Czas trwania do momentu."),
  G("Hurry up! The film ___ (start) by the time we get there.", ["will have started", "'ll have started"], "Zakończone przed przybyciem."),
  K("They will still be building the stadium in June.", "FINISHED", "They ___ the stadium by June.", ["won't have finished", "will not have finished", "won't have finished building", "will not have finished building"], "Przeciwny sens: nie skończą."),
  M("By the end of the course, you ___ over 2,000 words.", ["will have learnt", "will learn", "are learning", "will be learnt"], "will have learnt", "By the end → future perfect.", {"will learn": "Nie podkreśla zakończenia przed terminem.", "are learning": "Present continuous nie łączy się z by the end of.", "will be learnt": "Strona bierna – zły sens."}),
  G("I ___ (drive) past your house tomorrow, so I can drop it off.", ["will be driving", "'ll be driving"], "Naturalny bieg rzeczy."),
  T("Do 2040 roku ludzie wylądują na Marsie.", ["By 2040 people will have landed on Mars.", "By 2040, people will have landed on Mars.", "By 2040 humans will have landed on Mars.", "By 2040, humans will have landed on Mars."], "By + future perfect.")])
